<script lang="ts">
 import {formatHours,sumMinutes} from '#lib/project-time.js';
 import {localization} from '#lib/localization.js';
 import {canProject,day,ticketOrder,type Project,type Ticket,type Relation} from '#lib/projects.js';
 import ActionButton from '#lib/components/ActionButton.svelte';
 import SortableList from '#lib/components/SortableList.svelte';
 import SearchSelect from '#lib/components/SearchSelect.svelte';
 import StatusNotice from '#lib/components/StatusNotice.svelte';
 let {project,tickets,relations,view,statusIds,onopen,onmove,onchild,onorder,busy=false}:{project:Project;tickets:Ticket[];relations:Relation[];view:string;statusIds?:number[];onopen:(t:Ticket,el:HTMLElement|null)=>void;onmove:(t:Ticket,statusId:number)=>void;onchild:(t:Ticket)=>void;onorder:(t:Ticket,position:number)=>void;busy?:boolean}=$props();
 let ja=$derived($localization.displayLanguage==='ja');const tr=(j:string,e:string)=>ja?j:e;
 let collapsed=$state<number[]>([]),dragging=$state<number|null>(null),dismissedWarnings=$state('');
 let ordered=$derived(ticketOrder(tickets));
 let visible=$derived(ordered.filter(row=>{let p=row.ticket.parentId,depth=0;while(p!==null&&depth++<20){if(collapsed.includes(p))return false;p=tickets.find(t=>t.id===p)?.parentId??null;}return true;}));
 const status=(id:number)=>project.statuses.find(s=>s.id===id)?.name??'';
 const assignee=(id:number|null)=>{const p=project.members.find(m=>m.employeeId===id)?.employee;return p?p.lastName+' '+p.firstName:'';};
 const movable=(ticket:Ticket,id:number)=>project.status!=='archived'&&canProject(project,'tickets.update')&&project.typeStatuses.some(s=>s.typeId===ticket.typeId&&s.statusId===id);
 const droppable=(ticket:Ticket,id:number)=>!busy&&ticket.statusId!==id&&movable(ticket,id);
 let warnings=$derived(relations.filter(r=>r.kind==='finish_start').flatMap(r=>{const a=tickets.find(t=>t.id===r.fromId),b=tickets.find(t=>t.id===r.toId);return a?.dueOn&&b?.startsOn&&day(b.startsOn)<=day(a.dueOn)?[`${a.code} → ${b.code}`]:[];}));
 let dates=$derived(tickets.flatMap(t=>[t.startsOn,t.dueOn].filter((x):x is string=>!!x).map(d=>Date.parse(day(d)+'T00:00:00Z'))));
 let min=$derived(dates.length?Math.min(...dates):Date.now()),max=$derived(dates.length?Math.max(...dates):min),span=$derived(Math.max(1,(max-min)/86400000+1));
 const offset=(d:string)=>((Date.parse(day(d)+'T00:00:00Z')-min)/86400000)/span*100;
 const width=(t:Ticket)=>Math.max(0.5,(((Date.parse(day(t.dueOn??t.startsOn)+'T00:00:00Z')-Date.parse(day(t.startsOn??t.dueOn)+'T00:00:00Z'))/86400000)+1)/span*100);
 const aggregate=(root:Ticket,key:'estimatedMinutes'|'actualMinutes')=>{const ids=new Set([root.id]);let changed=true;while(changed){changed=false;for(const t of tickets)if(t.parentId!==null&&ids.has(t.parentId)&&!ids.has(t.id)){ids.add(t.id);changed=true;}}return sumMinutes(tickets.filter(t=>ids.has(t.id)).map(t=>t[key]??0));};
</script>
{#if warnings.length&&dismissedWarnings!==warnings.join()}<StatusNotice tone="warning" onDismiss={()=>dismissedWarnings=warnings.join()} message={tr('依存関係と日程が矛盾しています。日付は手動で修正してください：','Dependency dates conflict. Update dates manually: ')+warnings.join(', ')}/>{/if}
{#if view==='ticket-panel'}
 <div class="ticket-panel">
 {#each project.statuses.filter(s=>!statusIds||statusIds.includes(s.id)) as s (s.id)}<section class:drop-allowed={dragging!==null&&!!tickets.find(t=>t.id===dragging)&&droppable(tickets.find(t=>t.id===dragging)!,s.id)} aria-label={s.name} ondragover={e=>{const ticket=tickets.find(t=>t.id===dragging);if(ticket&&droppable(ticket,s.id))e.preventDefault();}} ondrop={e=>{e.preventDefault();const ticket=tickets.find(t=>t.id===dragging);if(ticket&&droppable(ticket,s.id))onmove(ticket,s.id);dragging=null;}}>
 <h3>{s.name} <small>{tickets.filter(t=>t.statusId===s.id).length}</small></h3>
 {#each tickets.filter(t=>t.statusId===s.id) as t (t.id)}<article draggable={movable(t,t.statusId)&&!busy} ondragstart={e=>{if(busy){e.preventDefault();return;}dragging=t.id;e.dataTransfer?.setData('text/plain',String(t.id));}} ondragend={()=>dragging=null}>
 <button class="ticket-link" onclick={e=>onopen(t,e.currentTarget)}><small>{t.code} · {project.types.find(x=>x.id===t.typeId)?.name}</small><strong>{t.title}</strong></button><p>{assignee(t.assigneeId)}{#if assignee(t.assigneeId)&&t.dueOn} · {/if}{day(t.dueOn)}</p>
 {#if canProject(project,'tickets.update')&&project.status!=='archived'}<SearchSelect field={'ticket-panel-status-'+t.id} label={tr('状態','Status')} value={String(t.statusId)} options={project.typeStatuses.filter(l=>l.typeId===t.typeId).sort((a,b)=>a.position-b.position).map(l=>({value:String(l.statusId),label:status(l.statusId)}))} searchable={false} disabled={busy} onSelect={v=>onmove(t,Number(v))}/>{/if}
 </article>{/each}
 </section>{/each}
 </div>
{:else if view==='gantt'}
 <!-- svelte-ignore a11y_no_noninteractive_tabindex (keyboard users must be able to scroll the timeline) -->
 <div class="gantt" role="region" aria-label={tr('ガントチャート','Gantt chart')} tabindex="0">
 <div class="gantt-head"><span>{tr('チケット','Ticket')}</span><span>{new Date(min).toISOString().slice(0,10)} → {new Date(max).toISOString().slice(0,10)}</span></div>
 {#each visible as {ticket:t,depth}}<div class="gantt-row"><button class="ticket-link" style:padding-left={Math.min(depth,10)*12+'px'} onclick={e=>onopen(t,e.currentTarget)}>{t.code} {t.title}</button><div class="timeline">{#if t.startsOn||t.dueOn}<button class="bar" class:milestone={project.types.some(type=>type.id===t.typeId&&type.milestone)} aria-label={`${t.title}: ${[day(t.startsOn),day(t.dueOn)].filter(Boolean).join(' → ')}`} style:left={offset(t.startsOn??t.dueOn!)+'%'} style:width={width(t)+'%'} onclick={e=>onopen(t,e.currentTarget)}>{day(t.startsOn)}{#if t.startsOn&&t.dueOn} → {/if}{day(t.dueOn)}</button>{/if}</div></div>{/each}
 </div>
 <ul class="dependencies">{#each relations.filter(r=>r.kind==='finish_start') as r}<li>{r.fromCode??''}{#if r.fromCode&&r.toCode} → {/if}{r.toCode??''} ({tr('終了→開始','Finish → start')})</li>{/each}</ul>
{:else}
 <!-- svelte-ignore a11y_no_noninteractive_tabindex (keyboard users must be able to scroll the table) -->
 <div class="table-wrap" tabindex="0" role="region" aria-label={tr('チケット一覧','Ticket list')}><SortableList table ids={visible.map(r=>r.ticket.id)} label={tr('チケットの順番を変更','Reorder tickets')} labelFor={id=>tickets.find(t=>t.id===id)?.title??''} groupFor={id=>String(tickets.find(t=>t.id===id)?.parentId??'root')} disabled={busy||!canProject(project,'tickets.update')||project.status==='archived'} onreorder={(_ids,moved,target)=>{const a=tickets.find(t=>t.id===moved),b=tickets.find(t=>t.id===target);if(a&&b)onorder(a,b.position);}}>{#snippet header()}<th>{tr('チケット','Ticket')}</th><th>{tr('種別／状態','Type / status')}</th><th>{tr('担当／期限','Assignee / due')}</th><th>{tr('見積／実績（時間）','Estimate / actual (hours)')}</th><th>{tr('操作','Actions')}</th>{/snippet}{#snippet children(id:number)}{@const row=visible.find(r=>r.ticket.id===id)!}{@const t=row.ticket}{@const depth=row.depth}<td><div class="tree-name" style:padding-left={Math.min(depth,10)*12+'px'}>{#if tickets.some(c=>c.parentId===t.id)}<button class="collapse" aria-expanded={!collapsed.includes(t.id)} aria-label={tr('子チケットの表示切替','Toggle children')+' '+t.title} onclick={()=>collapsed=collapsed.includes(t.id)?collapsed.filter(x=>x!==t.id):[...collapsed,t.id]}>{collapsed.includes(t.id)?'▸':'▾'}</button>{/if}<button class="ticket-link" onclick={e=>onopen(t,e.currentTarget)}><small>{t.code}</small> {t.title}</button></div>{#if t.parentId&&!tickets.some(p=>p.id===t.parentId)}<small>{tr('親チケット','Parent')}: {t.parentCode??''}</small>{/if}</td><td>{project.types.find(x=>x.id===t.typeId)?.name}<br/>{status(t.statusId)}</td><td>{assignee(t.assigneeId)}<br/>{day(t.dueOn)||''}</td><td>{formatHours(t.estimatedMinutes)} / {formatHours(t.actualMinutes??0)}{#if tickets.some(c=>c.parentId===t.id)}<small class="rollup">Σ {formatHours(aggregate(t,'estimatedMinutes'))} / {formatHours(aggregate(t,'actualMinutes'))}</small>{/if}</td><td><div class="row-actions">{#if canProject(project,'tickets.create')&&project.status!=='archived'}<ActionButton label={tr('子を追加','Add child')} disabled={busy||depth>=19} onclick={()=>onchild(t)}/>{/if}</div></td>{/snippet}</SortableList></div>
 <div class="mobile-tickets">
 <SortableList ids={visible.map(r=>r.ticket.id)} label={tr('チケットの順番を変更','Reorder tickets')} labelFor={id=>tickets.find(t=>t.id===id)?.title??''} groupFor={id=>String(tickets.find(t=>t.id===id)?.parentId??'root')} disabled={busy||!canProject(project,'tickets.update')||project.status==='archived'} onreorder={(_ids,moved,target)=>{const a=tickets.find(t=>t.id===moved),b=tickets.find(t=>t.id===target);if(a&&b)onorder(a,b.position);}}>{#snippet children(id:number)}{@const row=visible.find(r=>r.ticket.id===id)!}{@const t=row.ticket}{@const depth=row.depth}<article class="mobile-ticket" style:margin-left={Math.min(depth,5)*8+'px'}>
 <div class="tree-name">{#if tickets.some(c=>c.parentId===t.id)}<button class="collapse" aria-expanded={!collapsed.includes(t.id)} aria-label={tr('子チケットの表示切替','Toggle children')+' '+t.title} onclick={()=>collapsed=collapsed.includes(t.id)?collapsed.filter(x=>x!==t.id):[...collapsed,t.id]}>{collapsed.includes(t.id)?'▸':'▾'}</button>{/if}<button class="ticket-link" onclick={e=>onopen(t,e.currentTarget)}>{t.code} {t.title}</button></div>
 <p>{project.types.find(type=>type.id===t.typeId)?.name} · {status(t.statusId)}</p><p>{assignee(t.assigneeId)}{#if assignee(t.assigneeId)&&t.dueOn} · {/if}{day(t.dueOn)}</p><p>{tr('見積／実績（時間）','Estimate / actual (hours)')}: {formatHours(t.estimatedMinutes)} / {formatHours(t.actualMinutes??0)}</p>
 <div class="row-actions">{#if canProject(project,'tickets.create')&&project.status!=='archived'}<ActionButton label={tr('子を追加','Add child')} disabled={busy||depth>=19} onclick={()=>onchild(t)}/>{/if}</div>
 </article>{/snippet}</SortableList>
 </div>

{/if}
{#if !tickets.length}<p class="empty">{tr('チケットはありません。','No tickets.')}</p>{/if}
<style>
 .mobile-tickets{display:none}.mobile-ticket{padding:12px;border:1px solid var(--border);border-radius:var(--sph-radius-4px)}.mobile-ticket p{font-size:var(--font-size-support);color:var(--muted);margin:6px 0}.table-wrap{overflow:auto;max-width:100%}:global(.sortable-table){font-size:var(--font-size-support)}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--border);vertical-align:top}th{color:var(--muted);font-weight:500}th:nth-child(2){width:36%}.ticket-link{border:0;background:transparent;color:var(--text);font:inherit;text-align:left;cursor:pointer;overflow-wrap:anywhere;padding:0;min-height:32px}.ticket-link:hover{color:var(--action-primary)}.ticket-link small,.ticket-link strong{display:block}.tree-name{display:flex;align-items:start;gap:6px}.collapse{border:0;background:transparent;color:var(--text);cursor:pointer;min-width:24px;min-height:32px}.row-actions{display:flex;gap:6px;flex-wrap:wrap}small,.rollup{color:var(--muted);font-size:var(--font-size-support)}.rollup{display:block}.ticket-panel{display:flex;gap:16px;overflow-x:auto;padding:2px 0 16px}.ticket-panel section{background:var(--surface-hover);border:1px solid var(--border);border-radius:var(--sph-radius-4px);min-width:250px;flex:1;padding:12px}.ticket-panel h3{font-size:var(--font-size-body);margin:0 0 12px}.ticket-panel article{border:1px solid var(--border);border-radius:var(--sph-radius-4px);padding:12px;background:var(--surface);margin-bottom:10px}.ticket-panel article p{font-size:var(--font-size-support);color:var(--muted)}.ticket-panel section.drop-allowed{outline:2px dashed var(--action-primary)}.gantt{overflow:auto}.gantt-head,.gantt-row{display:grid;grid-template-columns:240px minmax(500px,1fr);min-width:740px}.gantt-head{font-size:var(--font-size-support);color:var(--muted);padding:8px 0}.gantt-row{border-bottom:1px solid var(--border);min-height:48px}.gantt-row>.ticket-link{padding-right:12px}.timeline{position:relative;min-height:48px;background:repeating-linear-gradient(to right,transparent 0,transparent calc(10% - 1px),var(--border) calc(10% - 1px),var(--border) 10%)}.bar{position:absolute;top:10px;height:28px;background:var(--action-primary);color:white;border:0;border-radius:4px;overflow:hidden;white-space:nowrap;font:inherit;font-size:12px;cursor:pointer}.bar.milestone{width:20px!important;min-width:20px;transform:translateX(-10px) rotate(45deg);font-size:0;height:20px;top:14px}.dependencies{font-size:var(--font-size-support);color:var(--muted)}.empty{text-align:center;padding:24px;color:var(--muted)}@media(max-width:700px){.mobile-tickets{display:grid;gap:12px}.table-wrap{display:none}th,td{padding:8px}:global(.sortable-table){min-width:660px}.ticket-panel section{min-width:260px}.ticket-link{min-height:44px}.collapse{min-height:44px}}
</style>
